llm.raw_content:
{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C23"],
      "claim": "Artemisinin, the closest structural analogue, is reported to have good absolute bioavailability after a single oral dose in malaria patients, supporting high F for a related polycyclic lactone natural product.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C16"],
      "claim": "Artesunate, an artemisinin derivative, showed 61% absolute oral bioavailability in Thai patients, indicating that this natural-product lactone class can achieve F at or above 20%.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C18"],
      "claim": "Artesunate and dihydroartemisinin showed 23% and 85% bioavailability, respectively, both above the 20% threshold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C15"],
      "claim": "Idarubicin, a lipophilic polycyclic natural product, had mean absolute oral bioavailability of 29.1%, supporting high F for a lipophilic polycyclic molecule.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C27"],
      "claim": "Gitoxin, a complex cardiac glycoside, had 96% oral bioavailability, showing that complex natural products can be well absorbed orally.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C35"],
      "claim": "Amphotericin B has negligible oral bioavailability, but its large polyene macrolide structure has very low transferability to the smaller triptolide-like query.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "low",
  "decision_summary": "The query is a small lipophilic polycyclic lactone natural product. The closest analogue artemisinin and its derivatives show absolute oral bioavailability values at or above 20% (23-85%), and other lipophilic natural products such as idarubicin (~29%) and gitoxin (96%) support high F. Qualitative 'low' reports for artemisinin lack threshold-specific F<20 evidence and are outweighed by numeric high-F data. Therefore predict high.",
  "evidence_gaps": [
    "No direct absolute oral bioavailability measurement for triptolide is present in the evidence set.",
    "All evidence molecules have low Morgan similarity (<0.19), limiting transferability.",
    "Qualitative low-bioavailability reports for artemisinin do not provide F values and are not threshold-specific.",
    "Low-F evidence from amphotericin B and baicalin has very low structural transferability to the query."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

